{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "DMP696, a close analogue sharing the branched alkoxyalkyl amino substituent and fused heteroaromatic core, showed brain concentrations over 150-fold higher than plasma-free levels after oral dosing, directly demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "NGP 555 was classified as BBB-permeable with a brain:plasma ratio of 0.93 in Tg2576 mice, providing direct quantitative evidence that this chemotype achieves adequate brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Compound 28 reached a brain/plasma ratio of 138% at 15 minutes in mice, showing brain accumulation and supporting CNS penetration for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Compounds 5i/5o exhibited greatly improved brain/plasma ratios (~10) and were not susceptible to P-glycoprotein-mediated efflux, indicating that related heteroaromatic amines can achieve good brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Oral administration of a close glycerol-derivative analogue produced brain concentrations of 435, 271, and 34 ng/mL at 2, 6, and 24 h in rats, demonstrating sustained brain exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate meaningful CNS access via direct brain/plasma ratios, brain concentrations, or BBB-permeability classifications; the query's shared heteroaromatic and alkoxyalkyl features support a pass.",
  "evidence_gaps": [
    "No direct in vivo pharmacokinetic data for the exact query molecule; prediction relies on high-transfer analogues.",
    "Exact efflux-transporter profile of the query is not directly measured, though close analogues show good brain exposure and one analogue family lacks P-gp susceptibility."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

